    h, w = len(out), len(out[0])
    for r in range(h):
        for c in range(w):
            if abs(r - cr) + abs(c - cc) == radius:
                out[r][c] = color


def find_diamonds(grid, color):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
    if not cells:
        return []

    candidates = []
    # Centers can lie just beyond an edge when a diamond is cropped.
    for cr in range(-8, h + 8):
        for cc in range(-8, w + 8):
            for radius in range(9):
                pattern = {
                    (r, c)
                    for r in range(h)
                    for c in range(w)
                    if abs(r - cr) + abs(c - cc) == radius
                }
                if pattern and pattern <= cells:
                    candidates.append((cr, cc, radius, pattern))

    best = None

    def search(remaining, chosen):
        nonlocal best
        if not remaining:
            if best is None or len(chosen) < len(best):
                best = chosen[:]
            return
        if best is not None and len(chosen) >= len(best):
            return

        cell = min(remaining, key=lambda x: sum(cell in p for *_, p in candidates))
        options = [cand for cand in candidates if cell in cand[3]]
        options.sort(key=lambda cand: len(cand[3]), reverse=True)
        for cand in options:
            search(remaining - cand[3], chosen + [cand])

    search(cells, [])
    if best is None:
        return [(r, c, 0) for r, c in cells]
    return [(cr, cc, radius) for cr, cc, radius, _ in best]

