def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(cell for row in grid for cell in row)
    a = counts.most_common(1)[0][0]
    b = next(color for color in counts if color != a)
    corners = [(0, 0), (0, w - 1), (h - 1, 0), (h - 1, w - 1)]
    start = None
    for r, c in corners:
        neighbors = []
        if r:
            neighbors.append(grid[r - 1][c])
        if r + 1 < h:
            neighbors.append(grid[r + 1][c])
        if c:
            neighbors.append(grid[r][c - 1])
        if c + 1 < w:
            neighbors.append(grid[r][c + 1])
        if neighbors and all(x == b for x in neighbors):
            start = (r, c)
            break
    out = [row[:] for row in grid]
    stack = [start]
