    while stack:
        r, c = stack.pop()
        out[r][c] = 8
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == a:
                seen.add((nr, nc))
                stack.append((nr, nc))
    return [row[::-1] for row in out[::-1]]

